-- ---------------------------------------------------------------- server-filled columns (never trusted from the client)
create or replace function private.fill_denorm() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  v_event uuid; v_div uuid; v_heat public.heats; v_att public.trick_attempts;
begin
  case tg_table_name
    when 'entries' then
      select d.event_id into v_event from public.divisions d where d.id = new.division_id;
      new.event_id := v_event;
    when 'rounds' then
      select d.event_id into v_event from public.divisions d where d.id = new.division_id;
      new.event_id := v_event;
    when 'panel_members' then
      select p.event_id into v_event from public.panels p where p.id = new.panel_id;
      new.event_id := v_event;
    when 'heats' then
      select r.event_id, r.division_id into v_event, v_div from public.rounds r where r.id = new.round_id;
      new.event_id := v_event;
      new.division_id := v_div;
    when 'trick_scores' then
      select * into v_att from public.trick_attempts a where a.id = new.attempt_id;
      new.event_id := v_att.event_id;
      new.heat_id := v_att.heat_id;
      v_event := v_att.event_id;
    else -- heat_slots, trick_attempts, impression_scores, penalties, heat_results
      select * into v_heat from public.heats h where h.id = new.heat_id;
      new.event_id := v_heat.event_id;
      v_event := v_heat.event_id;
      -- a rider can only be placed in, or log attempts for, a heat of their own division
      if tg_table_name in ('heat_slots', 'trick_attempts', 'impression_scores') and new.entry_id is not null then
        if not exists (select 1 from public.entries e where e.id = new.entry_id and e.division_id = v_heat.division_id) then
          raise exception 'ENTRY_NOT_IN_DIVISION';
        end if;
      end if;
  end case;
  if new.event_id is null then
    raise exception 'PARENT_NOT_FOUND';
  end if;
  return new;
end $$;

do $$
declare t text;
begin
  foreach t in array array['entries','rounds','panel_members','heats','heat_slots','trick_attempts','trick_scores','impression_scores','penalties','heat_results'] loop
    execute format('create trigger a_fill_denorm before insert on public.%I for each row execute function private.fill_denorm()', t);
  end loop;
end $$;
-- a heat can be re-parented only by the server; keep event/division in step with the round on update
create trigger a_fill_denorm_upd before update of round_id on public.heats for each row execute function private.fill_denorm();

-- ---------------------------------------------------------------- live counter (public pages poll on this)
create or replace function private.bump_live_rev() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  update public.heats set live_rev = live_rev + 1 where id = coalesce(new.heat_id, old.heat_id);
  return null;
end $$;

do $$
declare t text;
begin
  foreach t in array array['trick_attempts','trick_scores','impression_scores','penalties','heat_slots'] loop
    execute format('create trigger z_bump_live_rev after insert or update or delete on public.%I for each row execute function private.bump_live_rev()', t);
  end loop;
end $$;

-- ---------------------------------------------------------------- heat state machine: server time is truth
create or replace function private.heats_guard() returns trigger
language plpgsql as $$
declare
  priv boolean := current_user in ('service_role', 'postgres', 'supabase_admin');
  v_end timestamptz;
  v_started timestamptz := new.started_at; v_paused_at timestamptz := new.paused_at;
  v_paused_total int := new.paused_total_sec; v_ended timestamptz := new.ended_at; v_published timestamptz := new.published_at;
begin
  if not priv then
    -- server-owned columns cannot be edited by hand
    new.started_at := old.started_at; new.paused_at := old.paused_at; new.paused_total_sec := old.paused_total_sec;
    new.ended_at := old.ended_at; new.published_at := old.published_at; new.live_rev := old.live_rev;
    new.event_id := old.event_id; new.division_id := old.division_id; new.round_id := old.round_id;
    v_started := old.started_at; v_paused_at := old.paused_at; v_paused_total := old.paused_total_sec; v_ended := old.ended_at; v_published := old.published_at;
  end if;

  if new.status is distinct from old.status then
    if not priv and not (
      (old.status = 'scheduled' and new.status in ('running', 'cancelled')) or
      (old.status = 'running' and new.status in ('paused', 'ended', 'cancelled')) or
      (old.status = 'paused' and new.status in ('running', 'ended', 'cancelled')) or
      (old.status = 'ended' and new.status in ('under_review', 'cancelled')) or
      (old.status = 'under_review' and new.status in ('cancelled')) or
      (old.status = 'published' and new.status = 'under_review')
    ) then
      raise exception 'ILLEGAL_HEAT_TRANSITION: % -> %', old.status, new.status;
    end if;

    if old.status = 'scheduled' and new.status = 'running' then
      v_started := now();
    elsif old.status = 'running' and new.status = 'paused' then
      v_paused_at := now();
    elsif old.status = 'paused' and new.status = 'running' then
      v_paused_total := old.paused_total_sec + greatest(0, ceil(extract(epoch from (now() - coalesce(old.paused_at, now()))))::int);
      v_paused_at := null;
    elsif new.status = 'ended' and old.status in ('running', 'paused') then
      if old.status = 'paused' then
        v_ended := coalesce(old.paused_at, now());
      else
        v_end := old.started_at + make_interval(secs => old.duration_sec + old.paused_total_sec);
        v_ended := least(now(), coalesce(v_end, now()));
      end if;
    elsif new.status = 'published' then
      v_published := now();
    end if;

    -- privileged callers (publish, seeds, tests) may set a column explicitly; everyone else gets the computed value
    if not priv or new.started_at is not distinct from old.started_at then new.started_at := v_started; end if;
    if not priv or new.paused_at is not distinct from old.paused_at then new.paused_at := v_paused_at; end if;
    if not priv or new.paused_total_sec is not distinct from old.paused_total_sec then new.paused_total_sec := v_paused_total; end if;
    if not priv or new.ended_at is not distinct from old.ended_at then new.ended_at := v_ended; end if;
    if not priv or new.published_at is not distinct from old.published_at then new.published_at := v_published; end if;
  end if;
  return new;
end $$;

create trigger b_heats_guard before update on public.heats for each row execute function private.heats_guard();

-- ---------------------------------------------------------------- immutability (published results, audit trail)
create or replace function private.reject_change() returns trigger
language plpgsql as $$
begin
  if tg_op = 'DELETE' and current_setting('app.allow_purge', true) = 'on' then
    return old;
  end if;
  raise exception 'APPEND_ONLY: % on % is not allowed', tg_op, tg_table_name;
end $$;

create trigger a_append_only before update or delete on public.heat_results for each row execute function private.reject_change();
create trigger a_append_only before update or delete on public.audit_log for each row execute function private.reject_change();


-- ===== migration 20260929100300_audit.sql =====
-- Phase 3 / step 3: audit trigger. Who (user + seat), what, before, after, when, reason.
-- The reason and a friendlier action name arrive from the privileged functions through
-- transaction-local settings (app.reason, app.audit_action). Secrets are never copied into the log.
create or replace function private.audit_row() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  v_old jsonb := case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) end;
  v_new jsonb := case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) end;
  v_event uuid; v_seat uuid; v_action text;
begin
  v_old := v_old - 'pin_hash' - 'qr_token_hash';
  v_new := v_new - 'pin_hash' - 'qr_token_hash';
  v_event := (coalesce(v_new, v_old) ->> 'event_id')::uuid;
  select s.id into v_seat from public.judge_seats s where s.event_id = v_event and s.auth_user_id = auth.uid() and s.active limit 1;
  v_action := coalesce(nullif(current_setting('app.audit_action', true), ''), lower(tg_op));
  insert into public.audit_log (event_id, actor_user_id, actor_seat_id, action, table_name, row_id, before, after, reason)
  values (v_event, auth.uid(), v_seat, v_action, tg_table_name, (coalesce(v_new, v_old) ->> 'id')::uuid, v_old, v_new,
          nullif(current_setting('app.reason', true), ''));
  return null;
end $$;

do $$
declare t text;
begin
  foreach t in array array['trick_attempts','trick_scores','impression_scores','penalties','heat_results','judge_seats'] loop
    execute format('create trigger z_audit after insert or update or delete on public.%I for each row execute function private.audit_row()', t);
  end loop;
end $$;

-- Heats: only status / manual-override changes are worth a line (the live counter changes constantly).
create trigger z_audit after update on public.heats for each row
  when (old.status is distinct from new.status or old.manual_override is distinct from new.manual_override)
  execute function private.audit_row();


-- ===== migration 20260929100400_rls.sql =====
-- Phase 3 / step 4: Row Level Security on every table, least-privilege grants, safe views.
-- Rule of thumb: the database says who may do what; the app only asks.

-- ---------------------------------------------------------------- helper functions (security definer, so policies never recurse)
create or replace function private.is_org_member(p_org uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.memberships m where m.organisation_id = p_org and m.user_id = auth.uid());
$$;

create or replace function private.is_org_admin(p_org uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.memberships m where m.organisation_id = p_org and m.user_id = auth.uid() and m.role in ('owner', 'admin'));
$$;

create or replace function private.is_event_organiser(p_event uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from public.events e join public.memberships m on m.organisation_id = e.organisation_id
    where e.id = p_event and m.user_id = auth.uid());
$$;

create or replace function private.seat_id(p_event uuid) returns uuid
language sql stable security definer set search_path = '' as $$
  select s.id from public.judge_seats s
  where s.event_id = p_event and s.auth_user_id = auth.uid() and s.active and s.status = 'active' limit 1;
$$;

create or replace function private.seat_role(p_event uuid) returns text
language sql stable security definer set search_path = '' as $$
  select s.role from public.judge_seats s
  where s.event_id = p_event and s.auth_user_id = auth.uid() and s.active and s.status = 'active' limit 1;
$$;

create or replace function private.has_seat(p_event uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select private.seat_id(p_event) is not null;
$$;

create or replace function private.event_is_public(p_event uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.events e where e.id = p_event and e.status in ('published', 'live', 'complete'));
$$;

-- "ended" also covers a running heat whose timer has run out (no server process is needed to notice)
create or replace function private.heat_effective_status(p_heat uuid) returns text
language sql stable security definer set search_path = '' as $$
  select case when h.status = 'running' and h.started_at is not null
              and now() >= h.started_at + make_interval(secs => h.duration_sec + h.paused_total_sec)
         then 'ended' else h.status end
  from public.heats h where h.id = p_heat;
$$;

-- Setting for a division: the division's own override wins (even an explicit null = "unlimited"), else the scoring model.
create or replace function private.division_heat_setting(p_division uuid, p_key text) returns jsonb
language sql stable security definer set search_path = '' as $$
  select case when d.scoring_overrides -> 'heat' ? p_key then d.scoring_overrides -> 'heat' -> p_key else m.json -> 'heat' -> p_key end
  from public.divisions d left join public.scoring_models m on m.id = d.scoring_model_id
  where d.id = p_division;
$$;

-- May the calling judge write a mark for this heat right now? Panel member + heat running/paused (trick marks) or
-- ended within the grace period (trick and impression marks).
create or replace function private.judge_can_write(p_heat uuid, p_impression boolean) returns boolean
language plpgsql stable security definer set search_path = '' as $$
declare
  h public.heats; v_eff text; v_end timestamptz; v_grace int;
begin
  select * into h from public.heats where id = p_heat;
  if not found then return false; end if;
  if not exists (
    select 1 from public.divisions d
    join public.panel_members pm on pm.panel_id = d.panel_id
    join public.judge_seats s on s.id = pm.judge_seat_id
    where d.id = h.division_id and s.auth_user_id = auth.uid() and s.active and s.status = 'active'
  ) then return false; end if;
  v_eff := private.heat_effective_status(p_heat);
  if not p_impression and v_eff in ('running', 'paused') then return true; end if;
  if v_eff = 'ended' then
    v_end := coalesce(h.ended_at, h.started_at + make_interval(secs => h.duration_sec + h.paused_total_sec));
    select coalesce((e.settings ->> 'judgeGraceSec')::int, 180) into v_grace from public.events e where e.id = h.event_id;
    return v_end is not null and now() < v_end + make_interval(secs => v_grace);
  end if;
  return false;
end $$;

grant execute on all functions in schema private to anon, authenticated, service_role;

-- ---------------------------------------------------------------- privileges: start from nothing, grant only what is needed
revoke all on all tables in schema public from anon, authenticated;
revoke all on all functions in schema public from public, anon, authenticated;
